 "content": "def transform(grid):
    """Copy the vertical marker motif, centered on each marker, clipping at bounds."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    cols = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                cols.setdefault(c, []).append(r)
    source_col = max(cols, key=lambda c: len(cols[c]))
    top, bottom = min(cols[source_col]), max(cols[source_col])
    motif = [grid[r][source_col] for r in range(top, bottom + 1)]
    out = [row[:] for row in grid]
    center = len(motif) // 2
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    for r, c in markers:
        for i, value in enumerate(motif):
            rr = r + i - center
            if 0 <= rr < h:
                out[rr][c] = value
    return out

if __name__ == '__main__':
    grid = [[9] * 19 for _ in range(11)]
    grid[1][1], grid[2][1] = 7, 1
    for r in (3, 4, 5):
